/*
 * A055851  a(n) and floor(a(n)/6) are both squares; i.e., squares that remain
 *          squares when written in base 6 and last digit is removed.
 * https://oeis.org/A055851
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   not stated
 * Range:     u8 n <= 6, u16 n <= 9, u32 n <= 17, u64 n <= 24, u128 n <= 24,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  A055851 – Squares m^2 for which floor(m^2/6) is a square.
 *  The terms are generated by merging the three Pell sequences
 *  defined by m^2 – 6k^2 = d with d ∈ {1,3,4}.  Each sequence is
 *  produced by the recurrence obtained from multiplying by the unit
 *  5 + 2√6:
 *
 *      m' = 5*m + 12*k
 *      k' = 2*m + 5*k
 *
 *  The sequence starts with {0} and then sorted squares of the
 *  generated m values.  The function stores computed values in a
 *  static cache so that calls in any order are efficient.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stddef.h>

/* The build supplies the following types:
 *   idx_t – unsigned integer type for indices (e.g. uint64_t)
 *   seq_t – unsigned integer or big‑int type for sequence values
 */
extern seq_t a(idx_t n);                 /* prototype required by the build */

seq_t a(idx_t n)
{
    /* Static cache of already computed terms */
    static seq_t *cache      = NULL;
    static size_t  cache_cap = 0;
    static idx_t   cache_len = 0;

    /* Triple of Pell solutions (m,k) for d = 1, 3, 4 */
    static struct { seq_t m; seq_t k; } sol[3];
    static bool initialized = false;

    if (!initialized) {
        /* Seeds for the three equations */
        sol[0].m = 1;  sol[0].k = 0;   /* m^2 – 6k^2 = 1   */
        sol[1].m = 3;  sol[1].k = 1;   /* m^2 – 6k^2 = 3   */
        sol[2].m = 2;  sol[2].k = 0;   /* m^2 – 6k^2 = 4   */

        /* Allocate minimal cache and store the first term a(1) = 0 */
        cache_cap = 128;
        cache     = (seq_t *)malloc(cache_cap * sizeof(seq_t));
        cache[0]  = 0;
        cache_len = 1;
        initialized = true;
    }

    /* Generate terms until we have at least n of them */
    while (cache_len < n) {
        /* Find the smallest current m among the three sequences */
        int min_i = 0;
        for (int i = 1; i < 3; ++i) {
            if (sol[i].m < sol[min_i].m) {
                min_i = i;
            }
        }
        seq_t min_val = sol[min_i].m;

        /* Append square of the selected m */
        seq_t val = min_val * min_val;   /* overflow is defined for unsigned types */

        /* Grow cache if needed */
        if (cache_len >= cache_cap) {
            size_t new_cap = cache_cap ? cache_cap * 2 : 64;
            seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
            if (!tmp) {
                /* OOM – abort with a return of 0; in practice this should not happen */
                return 0;
            }
            cache     = tmp;
            cache_cap = new_cap;
        }
        cache[cache_len++] = val;

        /* Advance all sequences that currently equal the chosen minimum
         * (duplicates are possible, e.g. m = 27 appears in two sequences) */
        for (int i = 0; i < 3; ++i) {
            if (sol[i].m == min_val) {
                seq_t new_m = 5 * sol[i].m + 12 * sol[i].k;
                seq_t new_k = 2 * sol[i].m + 5  * sol[i].k;
                sol[i].m = new_m;
                sol[i].k = new_k;
            }
        }
    }

    /* Return the n‑th term (1‑based index) */
    return cache[n - 1];
}
